ALTER TABLE finansijski_izvjestaj_pozicije
ALTER COLUMN aop DROP NOT NULL;

WITH bilans_stanja_template AS (
  INSERT INTO finansijski_izvjestaj_sabloni (tip_sifra, naziv, sistemski)
  VALUES ('BILANS_STANJA', 'Bilans stanja', true)
  RETURNING id
), existing_template AS (
  SELECT id FROM bilans_stanja_template
  UNION ALL
  SELECT id FROM finansijski_izvjestaj_sabloni
  WHERE tip_sifra = 'BILANS_STANJA' AND sistemski = true AND agencija_id IS NULL AND firma_id IS NULL
  LIMIT 1
)
